// The words the contracts share (02 section 9; 15-TYPESCRIPT-PLAN section 2, addition 3). Types only.
//
// Each engine word list is derived from one list of values in packages/domain/src/core (vocab.ts, gate-verdict.ts);
// tests/domain holds each list equal to the old code it is copied from, named beside it. The six missing-value words
// and the moisture states are the schema's, generated by WP-06. The data and proposal states are new (02 section 9).

import type { MissingState, MoistureState } from '@atlas/data/rows';
import type { GATE_PRECEDENCE } from '../core/gate-verdict.ts';
import type {
  COLUMN_SETS, CONSTRAINT_KINDS, ENGINE_MISSING, EVIDENCE_LEVELS, GROUP_ORDER, LENSES, OPERATORS, PLOT_VIEWS, SCENARIO_KINDS,
  STATUSES, UNKNOWN_POLICIES,
} from '../core/vocab.ts';

// ------------------------------------------------------------------ data states

/** A change record's state in the workspace `change_log` table (02 section 9.2). */
export type ChangeStatus = 'draft' | 'exported' | 'merged';

/** A proposal's state (02 section 9.4). Only `held` carries a reason. */
export type ProposalState = 'pending' | 'accepted' | 'rejected' | 'held';

/**
 * The six words a cell may hold instead of a value: schema/vocab/missing-states.csv, generated into
 * packages/data (MISSING_STATES). Never 0, never blank.
 */
export type MissingWord = MissingState;

// ------------------------------------------------------------------ engine words

/** A requirement's answer: constraints.js STATUS (the strings, not the keys). */
export type Status = (typeof STATUSES)[number];

/** A product's or material's verdict across its requirements: evaluateMaterial gives only these three. */
export type Verdict = Exclude<Status, 'INDETERMINATE'>;

/** The group a result is listed in (D155): constraints.js GROUP_ORDER. */
export type Group = (typeof GROUP_ORDER)[number];

/** A print gate's verdict, best first: build/src/gates.js GATE_PRECEDENCE. The table of what each means: core/gate-verdict.ts. */
export type GateVerdict = (typeof GATE_PRECEDENCE)[number];

/** The engine's unknown policy: constraints.js UNKNOWN_POLICY. Strict leaves unknowns out; exploration keeps them flagged. */
export type UnknownPolicy = (typeof UNKNOWN_POLICIES)[number];

/** A requirement kind a scenario may hold: scenario.js KINDS. */
export type ScenarioKind = (typeof SCENARIO_KINDS)[number];

/** A kind the engine evaluates: evaluateConstraint's cases, the scenario's plus the engine's own 'treatment'. */
export type ConstraintKind = (typeof CONSTRAINT_KINDS)[number];

/** A numeric requirement's comparison: scenario.js OPERATORS, constraints.js compareInterval. */
export type ComparisonOperator = (typeof OPERATORS)[number];

/** A moisture service state a scenario asks about (D99, products.js statePolicy): a schema moisture state, never 'not-stated'. */
export type ServiceMoisture = Exclude<MoistureState, 'not-stated'>;

/** Which values decide: comparable only since D172 (scenario.js `evidence`; engine/products.js EVIDENCE). */
export type EvidenceLevel = (typeof EVIDENCE_LEVELS)[number];

/** The result view a scenario opens (scenario.js LENSES), its column set (COLUMN_SETS) and its chart view (WORKSPACE_VIEWS). */
export type Lens = (typeof LENSES)[number];
export type ColumnSet = (typeof COLUMN_SETS)[number];
export type PlotView = (typeof PLOT_VIEWS)[number];

/** Why the engine has no value (a result's `missing`): the words app/js/engine and build/src write. Not the six cell words. */
export type EngineMissing = (typeof ENGINE_MISSING)[number];

/** Who acted (owner ruled 2026-10-20, OQ-17 A): a person, or an agent with its model. */
export type ActorKind = 'human' | 'agent';
